-- FMH 179-sale import (attach to existing units). Company 71d33e07 / project ce05f4bb.
-- Applied live 2026-06-28 via Supabase API. Net 1,200,353,200 / received 427,167,590.
-- Source: FMH_Master_Import_CLEAN.xlsx. 140 clients (CNIC-deduped), 179 sales, 6719 installments, 949 payments.
-- Idempotency: staging tables are dropped/recreated; the DO block has no guard against
--   re-running (would violate sales_company_id_sale_number_key). Run once.

DROP TABLE IF EXISTS stg_fmh_clients, stg_fmh_bookings, stg_fmh_sched, stg_fmh_pays;
CREATE TABLE stg_fmh_clients(booking_no int, client_name text, father_name text, cnic text, phone text, address text);
CREATE TABLE stg_fmh_bookings(sale_no text, booking_no int, unit_no text, gross numeric, discount numeric, net numeric, received numeric, sale_person text, booking_date date);
CREATE TABLE stg_fmh_sched(sale_no text, unit_no text, sno int, due_date date, description text, amount numeric);
CREATE TABLE stg_fmh_pays(sale_no text, unit_no text, pay_date date, inst_no int, ptype text, amount numeric, note text);
