-- ============================================================================
-- FMH 179-sale import: attach to existing units. Atomic DO block (rolls back on
-- any failed check). Reads from stg_fmh_* staging tables loaded above.
-- Sales net_amount/total_amount/remaining_amount are GENERATED, so set
-- price_per_sqft=gross, area_sqft=1, discount=file -> total=gross, net=gross-discount.
-- Clients deduped by CNIC (placeholders null/blank/'0' stay per-booking).
-- Payments: amount>0 only (CHECK), Adjustment->'adjustment' else 'cash', null date->booking_date.
-- ============================================================================
DO $migr$
DECLARE
  c CONSTANT uuid := '71d33e07-e55c-49af-8f5b-fdd7fd6e8612';
  p CONSTANT uuid := 'ce05f4bb-a527-4e2b-b529-970c76c8d855';
  v_avail uuid; v_sold uuid;
  pre_fp text; post_fp text;
  bad int; n_sales int; g_net numeric; g_rec numeric; g_sched numeric;
  n_sold int; n_avail int;
BEGIN
  SELECT id INTO v_avail FROM category_unit_statuses WHERE company_id=c AND project_id=p AND status_code='AVAILABLE';
  SELECT id INTO v_sold  FROM category_unit_statuses WHERE company_id=c AND project_id=p AND status_code='SOLD';
  IF v_avail IS NULL OR v_sold IS NULL THEN RAISE EXCEPTION 'status ids missing'; END IF;

  SELECT count(*) INTO bad FROM stg_fmh_bookings b
    LEFT JOIN units u ON u.unit_no=b.unit_no AND u.company_id=c AND u.project_id=p
   WHERE u.id IS NULL;
  IF bad>0 THEN RAISE EXCEPTION 'STOP: % booking unit_no have no FMH unit row', bad; END IF;

  SELECT md5(string_agg(unit_no||'|'||base_price||'|'||area||'|'||coalesce(features->>'rate_per_sqft','')||'|'||coalesce(unit_type_id::text,''), ',' ORDER BY unit_no))
    INTO pre_fp FROM units WHERE company_id=c AND project_id=p;

  ALTER TABLE clients      DISABLE TRIGGER _trg_audit;
  ALTER TABLE sales        DISABLE TRIGGER _trg_audit;
  ALTER TABLE installments DISABLE TRIGGER _trg_audit;
  ALTER TABLE payments     DISABLE TRIGGER _trg_audit;
  ALTER TABLE units        DISABLE TRIGGER _trg_audit;
  ALTER TABLE payments     DISABLE TRIGGER trg_payment_health;
  ALTER TABLE payments     DISABLE TRIGGER trg_update_promise_on_payment;

  CREATE TEMP TABLE _ck ON COMMIT DROP AS
    SELECT cl.booking_no,
           CASE WHEN nullif(btrim(cl.cnic),'') IS NULL OR btrim(cl.cnic)='0'
                THEN 'NB:'||cl.booking_no::text ELSE 'C:'||btrim(cl.cnic) END AS ckey
    FROM stg_fmh_clients cl;

  CREATE TEMP TABLE _cl_new ON COMMIT DROP AS
  WITH rep AS (
    SELECT DISTINCT ON (k.ckey) k.ckey, cl.client_name, cl.father_name, cl.cnic, cl.phone, cl.address
    FROM _ck k JOIN stg_fmh_clients cl ON cl.booking_no=k.booking_no
    ORDER BY k.ckey, k.booking_no
  )
  SELECT ckey,
         'FMH-C-'||lpad((row_number() OVER (ORDER BY ckey))::text,4,'0') AS client_code,
         client_name, father_name,
         CASE WHEN ckey LIKE 'C:%' THEN substring(ckey from 3) ELSE NULL END AS cnic_norm,
         coalesce(btrim(phone),'') AS phone, address
  FROM rep;

  CREATE TEMP TABLE _cl_ins (ckey text, client_id uuid) ON COMMIT DROP;
  WITH ins AS (
    INSERT INTO clients (company_id, project_id, client_code, full_name, father_name, cnic, phone_primary, address, status)
    SELECT c, p, client_code, client_name, father_name, cnic_norm, phone, address, 'active'
    FROM _cl_new
    RETURNING id, client_code
  )
  INSERT INTO _cl_ins(ckey, client_id)
  SELECT n.ckey, i.id FROM ins i JOIN _cl_new n ON n.client_code=i.client_code;

  CREATE TEMP TABLE _bk_cli ON COMMIT DROP AS
    SELECT k.booking_no, ci.client_id FROM _ck k JOIN _cl_ins ci ON ci.ckey=k.ckey;

  INSERT INTO sales (company_id, project_id, sale_number, unit_id, client_id,
                     price_per_sqft, area_sqft, discount, sale_date, status, is_active,
                     payment_plan_type, installment_count, notes)
  SELECT c, p, b.sale_no, u.id, bc.client_id,
         b.gross, 1, b.discount, b.booking_date, 'active', true, 'installment',
         (SELECT count(*) FROM stg_fmh_sched s WHERE s.sale_no=b.sale_no),
         'Sale Person: '||b.sale_person
  FROM stg_fmh_bookings b
  JOIN units u ON u.unit_no=b.unit_no AND u.company_id=c AND u.project_id=p
  JOIN _bk_cli bc ON bc.booking_no=b.booking_no;

  INSERT INTO installments (company_id, project_id, sale_id, installment_number, due_date, amount_due, installment_type, status, notes)
  SELECT c, p, sa.id, s.sno, s.due_date, s.amount, 'installment', 'pending', s.description
  FROM stg_fmh_sched s
  JOIN sales sa ON sa.sale_number=s.sale_no AND sa.company_id=c;

  INSERT INTO payments (company_id, project_id, payment_code, sale_id, client_id, amount,
                        payment_date, payment_method, status, notes)
  SELECT c, p,
         'FMH-P-'||lpad((row_number() OVER (ORDER BY pm.sale_no, pm.pay_date NULLS FIRST, pm.inst_no))::text,5,'0'),
         sa.id, sa.client_id, pm.amount,
         COALESCE(pm.pay_date, b.booking_date),
         CASE WHEN pm.ptype='Adjustment' THEN 'adjustment' ELSE 'cash' END,
         'received',
         pm.ptype || CASE WHEN pm.note IS NOT NULL THEN ' — '||pm.note ELSE '' END
  FROM stg_fmh_pays pm
  JOIN sales sa ON sa.sale_number=pm.sale_no AND sa.company_id=c
  JOIN stg_fmh_bookings b ON b.sale_no=pm.sale_no
  WHERE pm.amount>0;

  WITH cum AS (
    SELECT i.id, i.amount_due, b.received,
           COALESCE(SUM(i.amount_due) OVER (PARTITION BY i.sale_id ORDER BY i.installment_number
                    ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS due_before
    FROM installments i
    JOIN sales sa ON sa.id=i.sale_id AND sa.company_id=c AND sa.project_id=p
    JOIN stg_fmh_bookings b ON b.sale_no=sa.sale_number
  ), alloc AS (
    SELECT id, amount_due, GREATEST(0, LEAST(amount_due, received - due_before)) AS paid FROM cum
  )
  UPDATE installments t
  SET amount_paid = a.paid,
      status = CASE WHEN a.amount_due>0 AND a.paid>=a.amount_due THEN 'paid'
                    WHEN a.paid>0 THEN 'partial' ELSE 'pending' END
  FROM alloc a WHERE t.id=a.id;

  UPDATE units SET status_id=v_sold
   WHERE company_id=c AND project_id=p AND unit_no IN (SELECT unit_no FROM stg_fmh_bookings);

  ALTER TABLE clients      ENABLE TRIGGER _trg_audit;
  ALTER TABLE sales        ENABLE TRIGGER _trg_audit;
  ALTER TABLE installments ENABLE TRIGGER _trg_audit;
  ALTER TABLE payments     ENABLE TRIGGER _trg_audit;
  ALTER TABLE units        ENABLE TRIGGER _trg_audit;
  ALTER TABLE payments     ENABLE TRIGGER trg_payment_health;
  ALTER TABLE payments     ENABLE TRIGGER trg_update_promise_on_payment;

  -- ===== VERIFY (a-g); any failure RAISEs -> full rollback =====
  SELECT count(*) INTO n_sales FROM sales WHERE company_id=c AND project_id=p;
  IF n_sales<>179 THEN RAISE EXCEPTION 'a: sales=% (<>179)', n_sales; END IF;
  IF EXISTS(SELECT 1 FROM sales WHERE company_id=c AND project_id=p AND (unit_id IS NULL OR client_id IS NULL))
     THEN RAISE EXCEPTION 'a: null unit_id/client_id present'; END IF;

  SELECT count(*) INTO bad FROM sales sa JOIN stg_fmh_bookings b ON b.sale_no=sa.sale_number
   WHERE sa.company_id=c AND (round(sa.net_amount)<>round(b.net) OR round(sa.total_amount)<>round(b.gross) OR round(sa.discount)<>round(b.discount));
  IF bad>0 THEN RAISE EXCEPTION 'b: net/gross/discount mismatch rows=%', bad; END IF;

  SELECT count(*) INTO bad FROM (
    SELECT sa.id, sa.net_amount, COALESCE(SUM(i.amount_due),0) sdue
    FROM sales sa LEFT JOIN installments i ON i.sale_id=sa.id
    WHERE sa.company_id=c AND sa.project_id=p GROUP BY sa.id, sa.net_amount) q
   WHERE round(sdue)<>round(net_amount);
  IF bad>0 THEN RAISE EXCEPTION 'c: schedule sum<>net rows=%', bad; END IF;

  SELECT count(*) INTO bad FROM (
    SELECT sa.id, b.received, COALESCE(SUM(pay.amount),0) spaid
    FROM sales sa JOIN stg_fmh_bookings b ON b.sale_no=sa.sale_number
    LEFT JOIN payments pay ON pay.sale_id=sa.id
    WHERE sa.company_id=c AND sa.project_id=p GROUP BY sa.id, b.received) q
   WHERE round(spaid)<>round(received);
  IF bad>0 THEN RAISE EXCEPTION 'd: payments sum<>received rows=%', bad; END IF;

  SELECT round(SUM(net_amount)) INTO g_net FROM sales WHERE company_id=c AND project_id=p;
  SELECT round(COALESCE(SUM(amount),0)) INTO g_rec FROM payments WHERE company_id=c AND project_id=p;
  SELECT round(COALESCE(SUM(amount_due),0)) INTO g_sched FROM installments i JOIN sales sa ON sa.id=i.sale_id WHERE sa.company_id=c AND sa.project_id=p;
  IF g_net<>1200353200 THEN RAISE EXCEPTION 'e: grand net=%', g_net; END IF;
  IF g_rec<>427167590 THEN RAISE EXCEPTION 'e: grand received=%', g_rec; END IF;
  IF g_sched<>1200353200 THEN RAISE EXCEPTION 'e: grand sched=%', g_sched; END IF;

  SELECT md5(string_agg(unit_no||'|'||base_price||'|'||area||'|'||coalesce(features->>'rate_per_sqft','')||'|'||coalesce(unit_type_id::text,''), ',' ORDER BY unit_no))
    INTO post_fp FROM units WHERE company_id=c AND project_id=p;
  IF post_fp<>pre_fp THEN RAISE EXCEPTION 'f: unit pricing fingerprint CHANGED'; END IF;

  SELECT count(*) INTO n_sold FROM units u JOIN category_unit_statuses s ON s.id=u.status_id
    WHERE u.company_id=c AND u.project_id=p AND s.status_code='SOLD';
  SELECT count(*) INTO n_avail FROM units u JOIN category_unit_statuses s ON s.id=u.status_id
    WHERE u.company_id=c AND u.project_id=p AND s.status_code='AVAILABLE';
  IF n_sold<>179 THEN RAISE EXCEPTION 'f: sold=% (<>179)', n_sold; END IF;
  IF n_avail<>273 THEN RAISE EXCEPTION 'f: available=% (<>273)', n_avail; END IF;

  IF EXISTS(SELECT 1 FROM sales sa WHERE sa.company_id=c AND sa.project_id=p
            AND sa.unit_id NOT IN (SELECT u.id FROM units u JOIN stg_fmh_bookings b ON b.unit_no=u.unit_no
                                   WHERE u.company_id=c AND u.project_id=p))
     THEN RAISE EXCEPTION 'g: sale on unexpected unit'; END IF;
  IF EXISTS(SELECT 1 FROM sales WHERE company_id=c AND project_id=p GROUP BY unit_id HAVING count(*)>1)
     THEN RAISE EXCEPTION 'g: duplicate sale per unit'; END IF;

  RAISE NOTICE 'IMPORT OK: sales=% net=% received=% sched=% sold=% avail=%', n_sales, g_net, g_rec, g_sched, n_sold, n_avail;
END $migr$;

DROP TABLE IF EXISTS stg_fmh_clients, stg_fmh_bookings, stg_fmh_sched, stg_fmh_pays;

